public class ExpressionEvaluatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            Expr leaf = new Num(7);
            check("eval a leaf", 7, ExpressionEvaluator.eval(leaf));
            check("show a leaf", "7", ExpressionEvaluator.show(leaf));

            Expr mixed = new Add(new Num(2), new Mul(new Num(3), new Num(4)));
            check("eval 2 + 3 * 4", 14, ExpressionEvaluator.eval(mixed));
            check("show 2 + 3 * 4", "(2 + (3 * 4))", ExpressionEvaluator.show(mixed));

            Expr negated = new Neg(new Add(new Num(5), new Num(-2)));
            check("eval -(5 + -2)", -3, ExpressionEvaluator.eval(negated));
            check("show -(5 + -2)", "-((5 + -2))", ExpressionEvaluator.show(negated));

            Expr deep = new Mul(new Neg(new Num(4)), new Add(new Num(1), new Neg(new Num(6))));
            check("eval a deeper tree", 20, ExpressionEvaluator.eval(deep));
            check("show a deeper tree", "(-(4) * (1 + -(6)))", ExpressionEvaluator.show(deep));

            check("eval null", 0, ExpressionEvaluator.eval(null));
            check("show null", "?", ExpressionEvaluator.show(null));
            check("a null branch counts as 0", 3, ExpressionEvaluator.eval(new Add(new Num(3), null)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

